/* Read-only examples. These never enter account data, public API records or chat. */
(() => {
 'use strict';
 const data=window.DISCOVERY_DEMO||{posts:[],projects:[],creators:[],events:[]};
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const route=(type,id)=>'#demo/'+type+'/'+encodeURIComponent(id);
 const badge='<span class="demo-badge">演示</span>';
 const find=(type,id)=>data[type].find(item=>item.id===id);
 const tags=values=>'<div class="tags">'+(values||[]).map(s=>'<span class="tag">'+esc(s)+'</span>').join('')+'</div>';
 const author=id=>find('creators',id)||{name:'示例创作者',skill:[],id:''};
 const avatar=a=>'<span class="demo-avatar" aria-hidden="true">'+esc(a.name.slice(0,1))+'</span>';
 const picture=(src,title,cls='')=>'<img class="demo-picture '+cls+'" src="'+esc(src)+'" alt="'+esc(title)+'原创演示封面" loading="lazy" width="960" height="540">';
 const matches=(values,q)=>!q||values.join(' ').toLowerCase().includes(q.trim().toLowerCase());
 const skills=a=>Array.isArray(a.skill)?a.skill:String(a.skill||'').split(/[,，、·]/).map(s=>s.trim()).filter(Boolean);
 function projectCard(p){const a=author(p.authorId);return '<article class="demo-work-card" data-demo-id="'+esc(p.id)+'"><a href="'+route('project',p.id)+'">'+picture(p.cover,p.title)+'<div class="demo-work-body"><div class="demo-title"><h3>'+esc(p.title)+'</h3>'+badge+'</div><p>'+esc(p.summary)+'</p><div class="demo-work-footer"><span>'+esc(a.name)+'</span>'+tags((p.tags||[]).slice(0,2))+'</div></div></a></article>';}
 function creatorCard(a){const works=data.projects.filter(p=>p.authorId===a.id);return '<article class="card creator-card demo-creator-card" data-demo-id="'+esc(a.id)+'"><a href="'+route('creator',a.id)+'"><div class="profile-top">'+avatar(a)+'<div><div class="demo-title"><h3>'+esc(a.name)+'</h3>'+badge+'</div><small class="muted">'+esc(a.headline||skills(a).join(' · '))+'</small></div></div>'+tags(skills(a).slice(0,3))+'<p>'+esc(a.bio)+'</p>'+(works[0]?'<div class="demo-creator-project">'+picture(works[0].cover,works[0].title)+'<span><small>正在做</small><strong>'+esc(works[0].title)+'</strong></span></div>':'')+'<span class="demo-open">查看档案 ↗</span></a></article>';}
 function postCard(p){const a=author(p.authorId),project=find('projects',p.projectId),lines=p.body.split('\n'),first=lines.shift(),lead=p.title||first,body=p.title?p.body:lines.join('\n');return '<article class="demo-post-card" data-demo-id="'+esc(p.id)+'"><div class="post-meta"><a href="'+route('creator',a.id)+'" aria-label="查看'+esc(a.name)+'的演示档案">'+avatar(a)+'</a><div><a class="post-author" href="'+route('creator',a.id)+'">'+esc(a.name)+'</a><small>'+({update:'作品进展',question:'提问交流',team:'寻找伙伴'}[p.kind]||'创作交流')+'</small></div>'+badge+'</div><a class="demo-post-body" href="'+route('post',p.id)+'"><h3>'+esc(lead)+'</h3><p>'+esc(body)+'</p></a>'+(project?'<a class="demo-post-project" href="'+route('project',project.id)+'">'+picture(project.cover,project.title)+'<span><small>关联作品</small><strong>'+esc(project.title)+'</strong><span>'+esc(project.summary)+'</span></span><b aria-hidden="true">↗</b></a>':'')+'<a class="demo-open" href="'+route('post',p.id)+'">查看帖子 ↗</a></article>';}
 function eventCard(e){return '<article class="demo-event-card" data-demo-id="'+esc(e.id)+'"><a href="'+route('event',e.id)+'">'+picture(e.cover,e.title)+'<div class="demo-event-body"><div class="demo-event-meta">'+badge+'<span>'+esc(e.format)+'</span><span>'+esc(e.duration)+'</span></div><h3>'+esc(e.title)+'</h3><p>'+esc(e.summary)+'</p>'+tags(e.theme?Array.isArray(e.theme)?e.theme:[e.theme]:[])+'<span class="demo-open">查看赛题 ↗</span></div></a></article>';}
 const projectCards=q=>data.projects.filter(p=>matches([p.title,p.summary,p.problem,p.solution,...(p.tags||[]),author(p.authorId).name],q)).map(projectCard).join('');
 const creatorCards=q=>data.creators.filter(a=>matches([a.name,a.bio,a.experience,...skills(a),...data.projects.filter(p=>p.authorId===a.id).map(p=>p.title)],q)).map(creatorCard).join('');
 const postCards=(kind='',q='')=>data.posts.filter(p=>(!kind||p.kind===kind)&&matches([p.body,author(p.authorId).name],q)).map(postCard).join('');
 const note='<p class="demo-detail-note">演示内容：人物、作品和活动均为虚构，不提供报名、私聊或官方认证。</p>';
 const back=(href,label)=>'<a class="text-button demo-back" href="'+href+'">← '+label+'</a>';
 const section=(title,body)=>'<section class="demo-detail-section"><h2>'+title+'</h2>'+body+'</section>';
 const paragraph=v=>'<p>'+esc(v)+'</p>';
 const list=items=>'<ul>'+(Array.isArray(items)?items:[items]).filter(Boolean).map(v=>'<li>'+esc(typeof v==='string'?v:v.text||v.description||[v.version,v.title,v.body,v.note].filter(Boolean).join(' · '))+'</li>').join('')+'</ul>';
 function detail(type,id){
  const group={project:'projects',creator:'creators',post:'posts',event:'events'}[type],item=group&&find(group,id);
  if(!item)return '<div class="page-narrow"><h1>没有这条演示内容</h1>'+back('#home','返回首页')+'</div>';
  if(type==='project'){const a=author(item.authorId);return '<div class="demo-detail-page">'+back('#discover','返回作品')+'<div class="demo-detail-heading"><div><div class="demo-title"><h1>'+esc(item.title)+'</h1>'+badge+'</div>'+paragraph(item.summary)+'</div><a class="text-button" href="'+route('creator',a.id)+'">'+esc(a.name)+' ↗</a></div>'+picture(item.cover,item.title,'demo-detail-cover')+'<div class="demo-detail-columns"><div>'+section('解决什么问题',paragraph(item.problem))+section('怎么做',paragraph(item.solution))+section('制作记录',list(item.changelog))+'</div><aside>'+section('创作者',creatorCard(a))+section('负责的部分',paragraph(item.role))+section('用到的技能',tags(item.tags))+'</aside></div>'+note+'</div>';}
  if(type==='creator'){const works=data.projects.filter(p=>p.authorId===id),posts=data.posts.filter(p=>p.authorId===id);return '<div class="demo-detail-page">'+back('#creators','返回创作者')+'<section class="demo-creator-profile">'+avatar(item)+'<div><div class="demo-title"><h1>'+esc(item.name)+'</h1>'+badge+'</div>'+paragraph(item.bio)+tags(skills(item))+'</div></section>'+section('创作经历',list(item.experience))+section('作品','<div class="work-grid">'+works.map(projectCard).join('')+'</div>')+section('创作动态',posts.map(postCard).join(''))+note+'</div>';}
  if(type==='post'){const a=author(item.authorId);return '<div class="demo-detail-page demo-post-detail">'+back('#home','返回首页')+postCard(item)+section('关于创作者','<a class="text-button" href="'+route('creator',a.id)+'">'+esc(a.name)+' · 查看档案 ↗</a>')+note+'</div>';}
  return '<div class="demo-detail-page">'+back('#events','返回比赛')+picture(item.cover,item.title,'demo-detail-cover')+'<div class="demo-detail-heading"><div><div class="demo-title"><h1>'+esc(item.title)+'</h1>'+badge+'</div>'+paragraph(item.summary)+'</div></div><div class="demo-detail-columns"><div>'+section('这次挑战',paragraph(item.description||item.summary))+section('提交什么',list(item.deliverables))+'</div><aside>'+section('赛制','<dl class="demo-facts"><div><dt>主题</dt><dd>'+esc(Array.isArray(item.theme)?item.theme.join(' · '):item.theme)+'</dd></div><div><dt>形式</dt><dd>'+esc(item.format)+'</dd></div><div><dt>时间</dt><dd>'+esc(item.duration)+'</dd></div></dl>')+section('参赛工具','<a class="btn primary" href="#prepare">生成准备建议</a>')+'</aside></div>'+note+'</div>';
 }
 function search(q){const projects=projectCards(q),creators=creatorCards(q),posts=postCards('',q),events=data.events.filter(e=>matches([e.title,e.summary,e.theme],q)).map(eventCard).join('');return (projects?section('演示作品','<div class="work-grid">'+projects+'</div>'):'')+(creators?section('演示创作者','<div class="creator-grid">'+creators+'</div>'):'')+(posts?section('演示帖子',posts):'')+(events?section('演示比赛','<div class="demo-event-grid">'+events+'</div>'):'');}
 window.DiscoveryDemos=Object.freeze({projectCards,creatorCards,postCards,eventCards:()=>data.events.map(eventCard).join(''),detail,search});
})();
